def read(path: Path):
    return json.loads(path.read_text(encoding="utf-8"))


def dedupe(values):
    return list(dict.fromkeys(v for v in values if isinstance(v, str) and v.strip()))


def source_kind(url: str) -> str:
    u = url.lower()
    if any(x in u for x in ("statsmodels.org", "quantlib.org", "quantlib-python-docs.readthedocs.io", "quantlibguide.com", "arch.readthedocs.io", "strata.opengamma.io", "github.com/lballabio/quantlib", "github.com/lballabio/quantlib-swig", "developer.apollo.auto", "carla.readthedocs.io", "stat.ethz.ch/r-manual", "scikit-learn.org", "scipy.org/doc", "bashtage.github.io/linearmodels")):
        return "maintained_technical_documentation"
    if "onetonline.org" in u:
        return "official_occupational_tasks_skills"
    if "data.europa.eu/esco" in u or "esco.ec.europa.eu" in u:
        return "official_occupational_classification"
    if "iso.org" in u or "sae.org" in u or "saemobilus.sae.org" in u or "shopulstandards.com" in u:
        return "standards_body"
    if "nhtsa.gov" in u or "federalreserve.gov" in u or "bis.org" in u:
        return "regulator_or_public_agency"
    if ("cfainstitute.org" in u or "garp.org" in u or "maths.ox.ac.uk" in u or "math.columbia.edu" in u or "ocw.mit.edu" in u
            or "mitsloan.mit.edu" in u or "haas.berkeley.edu" in u or "datascience.duke.edu" in u
            or "uchicago.edu" in u or "umich.edu" in u or "nus.edu.sg" in u or "smu.edu.sg" in u):
        return "professional_or_academic_curriculum"
    if any(x in u for x in ("docs.autoware.org", "autowarefoundation.github.io", "carla.readthedocs.io")):
        return "maintained_project_documentation"
    if any(x in u for x in ("nvidia.", "tesla.com", "rivian.com", "aeva.com", "lever.co", "daimlertruck.com", "gm.com", "avaron.se", "mobileye.com", "janestreet.com", "citadel.com", "citi.com", "point72.com", "aramco.com", "vestas.com", "zurich.com", "aig.com", "amundi.com", "aurora.tech", "maymobility.com", "jpmorgan.com", "jpmc.fa.oraclecloud.com", "careers.blackrock.com", "fordfoundation.wd1.myworkdayjobs.com", "aaaie.wd1.myworkdayjobs.com", "careers.withwaymo.com")):
        return "employer_or_industry_grey_literature"
    if "indeed.com" in u:
        return "job_listing_aggregator_grey_literature"
    if "automotive-skills-alliance.eu" in u:
        return "industry_project_grey_literature"
    if "oecd.org" in u or "iosco.org" in u:
        return "intergovernmental_or_industry_guidance"
    return "existing_external_reference_requires_claim_level_review"


def grey_credibility_assessment(record: dict) -> str | None:
    """Provide a bounded credibility judgement for grey sources when absent."""
    family = str(record.get("source_family", "")).casefold()
    publisher = record.get("publisher", "the named publisher")
    limit = str(record.get("claim_limit", "")).strip()
    if "job posting" in family or ("employer" in family and "posting" in family):
        base = f"Credible for the named employer's stated duties because {publisher} is accountable for this posting; it is time-sensitive and represents one position/employer, so it cannot establish occupational prevalence or a universal requirement."
    elif "dataset" in family or "benchmark" in family:
        base = f"Credible as a first-party description of the dataset/benchmark because {publisher} publishes or maintains it and documents its contents and scope; provider interests, geography, collection design, licensing and benchmark limits constrain generalization. Benchmark performance does not establish real-world safety."
    elif "vendor" in family or "project" in family or "technical documentation" in family:
        base = f"Credible as primary documentation of {publisher}'s own product, architecture or implementation claims; it is provider-authored, so corroborate field-wide claims, comparative performance and safety implications independently."
    elif "standard" in family or "guidance" in family or "regulat" in family or "prudential" in family:
        base = f"Credible for the issuing body's stated framework and scope ({publisher}); applicability depends on jurisdiction, adoption/status and edition date. It should not be generalized beyond that scope or treated as empirical proof of outcomes."
    elif "labor-market" in family or "onet" in family or "occupational" in family:
        base = f"Credible as a bounded occupational/labor-market record from {publisher}; classification, geography, period and sampling coverage limit transfer to other markets and named roles."
    elif "curriculum" in family or "professional body" in family:
        base = f"Credible for {publisher}'s stated curriculum or practice framework and its dated scope; it is not by itself a field-wide consensus, universal job requirement or proof of learning order."
    elif "grey" in family or "community" in family or "practitioner" in family:
        base = f"Credible only for the bounded, inspectable claim identified here because the publisher is attributable ({publisher}); assess authorship, date, source trail, conflicts and independent corroboration before generalizing."
    else:
        return None
    return base + (f" Recorded claim limit: {limit}" if limit else "")


def current_access_status(url: str):
    note = D166_REOPENED_ROLE_URLS.get(url) or VERIFIED_THIS_PASS.get(url)
    if not note and url:
        # Reviewed role-reference annotations also carry a source-specific
        # note. Use that note for access status instead of leaving a reviewed
        # card looking uninspected simply because it was not a separate task
        # posting in VERIFIED_THIS_PASS.
        reviewed_card = named_role_source_card(url, "")
        if reviewed_card.get("reviewed_in_this_pass"):
            note = reviewed_card.get("current_pass_note")
    if not note:
        return {"reviewed_in_this_pass": False, "current_pass_note": None}
    lowered = note.casefold()
    if "official nvidia careers search result text inspected" in lowered:
        status = "official_search_result_inspected_direct_fetch_limited"
    elif "redirects to" in lowered or "http 404" in lowered or "404 not found" in lowered or "http 410" in lowered or "http 403" in lowered or "not accessible" in lowered or "inaccessible" in lowered:
        status = "reopened_but_original_page_unavailable_or_stale"
    elif "no readable text" in lowered:
        status = "reopened_fetch_status_unresolved"
    elif "accessible" in lowered or "opened" in lowered or "inspected" in lowered or "reopened" in lowered:
        status = "reopened_and_inspected"
    else:
        status = "reopened_status_requires_review"
    return {"reviewed_in_this_pass": True, "current_pass_note": note, "current_access_status": status}


def load_reconciliation_module():
    spec = importlib.util.spec_from_file_location("d011_d166_recon", RECON_SCRIPT)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Cannot load {RECON_SCRIPT}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def collect_urls(value):
    found = []
    if isinstance(value, str):
        found.extend(re.findall(r"https?://[^\s\]\)\"']+", value))
    elif isinstance(value, dict):
        for child in value.values():
            found.extend(collect_urls(child))
    elif isinstance(value, list):
        for child in value:
            found.extend(collect_urls(child))
    return [u.rstrip(".,;") for u in found]


