CURATED_SOURCE_CARDS.extend([
    {"source_id":"D166-AUTOWARE-VEHICLE-INTERFACE-DESIGN-2026","domain_id":"D166","publisher":"Autoware Foundation","title":"Vehicle Interface Design","url":"https://autowarefoundation.github.io/autoware-documentation/latest/design/autoware-architecture/vehicle/","source_family":"maintained project architecture documentation / credible grey literature","locator":"Inspected 2026-10-23. Defines a hardware-independent internal interface and a vehicle-specific adapter; translates normalized acceleration/braking/steering commands to platform formats and returns normalized velocity, steering, actuation, odometry and control-mode feedback. Also lists feature discovery, warnings, disengagement/manual intervention, and optional vehicle commands.","supports":"Concrete system-integration responsibilities and command/status data contracts between ADS software, drive-by-wire vehicle platforms, control and localization consumers.","claim_limit":"Autoware's reference architecture and feature examples; it does not prescribe universal response-time or accuracy targets, vehicle-specific implementation, or regulatory/safety approval.","credibility_assessment":"High for Autoware's own architecture because this is the maintained first-party documentation; generalization to closed or differently architected vehicles requires corroboration.","search_status":"reopened and inspected 2026-10-23"},
    {"source_id":"D166-AUTOWARE-RAW-VEHICLE-CMD-CONVERTER-2026","domain_id":"D166","publisher":"Autoware Foundation","title":"Autoware Raw Vehicle Command Converter","url":"https://autowarefoundation.github.io/autoware_universe/main/vehicle/autoware_raw_vehicle_cmd_converter/","source_family":"maintained project module documentation / credible grey literature","locator":"Inspected 2026-10-23. Converts control targets to vehicle actuation signals, converts steering-wheel/tire-angle feedback, documents vehicle gear-ratio compensation and control-pipeline latency measurement; labels the vehicle-adaptor feature under development.","supports":"Practical platform-adaptation, feedback normalization and latency-observability examples at the boundary between motion control and vehicle interface integration.","claim_limit":"Implementation-specific and partly under development; coefficients and command semantics are vehicle dependent. It does not show every production interface or guarantee closed-loop performance.","credibility_assessment":"High for the Autoware module's behavior and stated implementation status because the maintainer documents the module; limits are explicit in the documentation.","search_status":"reopened and inspected 2026-10-23"},
    {"source_id":"D166-APOLLO-CHASSIS-COMMAND-SCHEMA-2026","domain_id":"D166","publisher":"ApolloAuto","title":"Apollo ChassisCommand Protobuf Schema","url":"https://github.com/ApolloAuto/apollo/blob/master/modules/common_msgs/external_command_msgs/chassis_command.proto","source_family":"maintained open-source interface schema / credible grey literature","locator":"Inspected 2026-10-23. Schema includes a command ID, standard vehicle signals and an extensible custom-operation field.","supports":"A concrete example of typed command identity and extensible vehicle-command schema design in an AV software stack.","claim_limit":"Apollo's message schema only; it is not an interoperable industry standard and does not specify the complete vehicle network, actuation dynamics, diagnostics or safety case.","credibility_assessment":"High for the current Apollo schema because the first-party maintained repository is the primary artifact; conclusions are limited to that software stack.","search_status":"reopened and inspected 2026-10-23"},
    {"source_id":"D166-ITU-T-UNIVERSAL-ADS-INTERFACES-2025","domain_id":"D166","publisher":"ITU-T","title":"Functional Requirements of Universal Interfaces for Purpose-Built ADS-Dedicated Vehicles","url":"https://www.itu.int/epublications/publication/itu-t-f-749-17-2025-12-functional-requirements-of-universal-interfaces-for-purpose-built-automated-driving-system-dedicated-vehicle","source_family":"international telecommunications recommendation / standards-body guidance","locator":"ITU-T F.749.17 (12/2025), inspected 2026-10-23. Scoped to purpose-built ADS-dedicated vehicles; discusses modular and vendor-agnostic interfaces, sensor integration, V2X, inter-subsystem data exchange and verification concepts.","supports":"Standards-oriented comparison point for modular interfaces and integration across ADS, vehicle platform, application and infrastructure subsystems.","claim_limit":"Purpose-built ADS-DV scope and recommendation status matter. Do not apply its numerical examples as universal thresholds or imply jurisdictional adoption; trace normative references and edition before implementation.","credibility_assessment":"High authority for the published recommendation's stated scope and text; applicability is narrow and not evidence that all listed interface practices are deployed or legally required.","search_status":"official recommendation page inspected 2026-10-23"},
])

